# Remove the minimum number of parentheses to make the string valid

def minRemoveToMakeValid(s: str) -> str:
    # First pass: remove all extra ")" and remember positions of "("
    result = []
    open_count = 0
    for c in s:
        if c == '(': 
            open_count += 1
            result.append(c)
        elif c == ')':
            if open_count > 0:
                open_count -= 1
                result.append(c)
            # else: skip extra ')' (no match)
        else:
            result.append(c)
    # Second pass: remove unmatched '('
    final = []
    open_to_remove = open_count
    for c in reversed(result):
        if c == '(' and open_to_remove > 0:
            open_to_remove -= 1
            continue  # Remove from right
        final.append(c)
    return ''.join(reversed(final))
